Ext._define('cif.property.PropertyGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'cif.property.PropertyWindow',

    configOrderToolBar: ['add', 'edit', 'remove','-', 'confirmNotProperty', '-', 'confirmCheck', '-', 'search',],

    getConfirmCheckAction: function(cfg) {
        if(!this.actionconfirm)
            this.actionconfirm = Ext._create('Ext.Button', {
                text: 'Confirmar Informação',
                iconCls: 'icon-cif icon-cif-accept',
                scope: this,
                handler: this.confirmAction
            });
    
        return this.actionconfirm;
    },

    getConfirmNotPropertyAction: function(cfg) {
        if(!this.actionNotProperty)
            this.actionNotProperty = Ext._create('Ext.Button', {
                text: 'Não possuo bens e valores',
                iconCls: 'icon-cif icon-cif-cash-minus',
                scope: this,
                handler: this.confirmNotProperty
            });
    
        return this.actionNotProperty;
    },

    confirmAction: function(){
        var selection = this.getSelectionModel().getSelections();
         
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

        if(selection.length > 0) {
            mask.show();

            rest.doRequest(
                rest.getRoute('confirm_action', false, 'POST', {
                    scope: this,
                    params: {
                        pks: selection.map(function(item) { return item.get('pk') })
                    },
                    callback: function() {
                        mask.hide();
                        mask = undefined;
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success) {
                            this.getStore().reload();
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.INFO,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                        }
                        else
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponível no momento.'
                        });
                    },
                })
            );
        }
        else Ext.Msg.show({
            'title': 'Atenção',
            'icon': Ext.Msg.ERROR,
            'buttons': Ext.Msg.OK,
            'msg': 'Selecione pelo menos um item.'
        });
    },

    confirmNotProperty: function(){
        
        console.log(this.idMember);
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

        mask.show();

        rest.doRequest(
            rest.getRoute('confirm_not_property', false, 'POST', {
                scope: this,
                params: {
                    pk_member: this.idMember
                },
                callback: function() {
                    mask.hide();
                    mask = undefined;
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success) {
                        this.getStore().reload();
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                    }
                    else
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                },
                failure: function(xhr) {
                    Ext.Msg.show({
                        title: 'Atenção',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Recurso indisponível no momento.'
                    });
                },
            })
        );
    },

    getLastYear: function(){
        var dataAtual = new Date();
        var ano = dataAtual.getFullYear()-1
        return '31/12/'+ano;
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 120, renderer: core.rendererIconGrid},
                    {header: 'Código', dataIndex: 'code_unicode', width:100},
                    {header: 'Descrição', dataIndex: 'description', id: 'autoExpandColumn'},
                    {header: 'Situação R$ em: ' + this.getLastYear(), dataIndex: 'current_value', renderer: toolkit.util.formatCurrency, width: 160},
                    {header: 'País', dataIndex: 'country_unicode', width: 90},
                    {header: 'Referência', dataIndex: 'refperiod_property_unicode', width: 200},
                    {header: 'Criado em', dataIndex: 'created_at', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y') , hidden: true},
                    {header: 'Atualizado em', dataIndex: 'modified_at', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y') , hidden: true},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'cif.property.PropertyRestful',
    'cif.property.PropertyGrid'
);

